def count_numbers_with_power_of_two(limit, power):
    power_of_two_str = str(2 ** power)
    length = len(power_of_two_str)

    @lru_cache(None)
    def dp(pos, match, tight):
        if pos == length:
            return match

        res = 0
        max_digit = int(input_str[pos]) if tight else 9
        for digit in range(max_digit + 1):
            new_match = match or (digit == int(power_of_two_str[match]))
            res += dp(pos + 1, new_match, tight and (digit == max_digit))

        return res

    input_str = str(limit)
