from collections import Counter

def count_numbers_with_power_of_two(limit, power):
    target = 2 ** power
    target_str = str(target)
    target_len = len(target_str)

    dp = [[0] * (target_len + 1) for _ in range(10)]
    dp[0][0] = 1

    for i in range(10):
        dp[i][0] = 1
        for j in range(target_len):
            dp[i][j + 1] = dp[i][j]
            if i >= int(target_str[j]):
                dp[i][j + 1] += dp[i - int(target_str[j])][j]

    def count_numbers(num):
        num_str = str(num)
        num_len = len(num_str)

        if num_len < target_len:
            return 0

        result = 0
        prefix_sum = [0] * (target_len + 1)
        prefix_sum[0] = dp[0][target_len]
        for i in range(1, 10):
            prefix_sum[i] = prefix_sum[i - 1] + dp[i][target_len]

        for i in range(num_len):
            digit = int(num_str[i])
            less_count = prefix_sum[digit]
            more_count = dp[digit][target_len]

            for j in range(digit):
                if str(j) in target_str:
                    less_count -= dp[j][target_len - (i + 1)]

            if str(digit) in target_str:
                less_count -= dp[digit][target_len - (i + 1)]

            if str(digit) in target_str[:i]:
                more_count -= dp[digit][target_len - (i + 1)]

            result += less_count * (10 ** (num_len - i - 1)) + more_count

            if i > 0 and str(digit) == target_str[0:i]:
                break

        return result

    return count_numbers(limit + 1)

