def count_numbers_with_power_of_two(n, e):
    power_of_two = str(2 ** e)
    count = 0
    power_length = len(power_of_two)

    if power_length == 1:
        return sum(1 for i in range(n + 1) if str(i).count(power_of_two[0]) > 0)

